CREATE TABLE IF NOT EXISTS `reader_progress` (`fileId` INTEGER NOT NULL, `cfi` TEXT, `percentage` REAL NOT NULL, `updatedAt` INTEGER NOT NULL, `dirty` INTEGER NOT NULL, PRIMARY KEY(`fileId`));
CREATE TABLE IF NOT EXISTS `audio_progress` (`bookId` INTEGER NOT NULL, `currentFileId` INTEGER NOT NULL, `positionSeconds` REAL NOT NULL, `percentage` REAL NOT NULL, `updatedAt` INTEGER NOT NULL, `dirty` INTEGER NOT NULL, PRIMARY KEY(`bookId`));
CREATE TABLE IF NOT EXISTS `downloads` (`bookId` INTEGER NOT NULL, `title` TEXT, `authors` TEXT NOT NULL, `narrators` TEXT NOT NULL, `isAudiobook` INTEGER NOT NULL, `format` TEXT, `sizeBytes` INTEGER NOT NULL, `downloadedAt` INTEGER NOT NULL, `coverLocalPath` TEXT, `bookJson` TEXT NOT NULL, `filesJson` TEXT NOT NULL, `status` TEXT NOT NULL, `progress` REAL NOT NULL, `lastError` TEXT, PRIMARY KEY(`bookId`));
CREATE TABLE IF NOT EXISTS `pending_ratings` (`bookId` INTEGER NOT NULL, `rating` INTEGER, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`bookId`));
CREATE TABLE IF NOT EXISTS `pending_read_status` (`bookId` INTEGER NOT NULL, `status` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`bookId`));
CREATE TABLE IF NOT EXISTS `pending_reading_sessions` (`sessionId` TEXT NOT NULL, `fileId` INTEGER NOT NULL, `sessionType` TEXT NOT NULL, `startedAt` INTEGER NOT NULL, `endedAt` INTEGER NOT NULL, `durationSeconds` INTEGER NOT NULL, `progressDelta` REAL, `endProgress` REAL, PRIMARY KEY(`sessionId`));
CREATE TABLE IF NOT EXISTS `pending_annotation_ops` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `bookId` INTEGER NOT NULL, `kind` TEXT NOT NULL, `annotationId` INTEGER NOT NULL, `cfi` TEXT, `text` TEXT, `color` TEXT, `note` TEXT, `noteSet` INTEGER NOT NULL, `chapterTitle` TEXT, `bookFileId` INTEGER, `createdAt` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `annotation_cache` (`bookId` INTEGER NOT NULL, `json` TEXT NOT NULL, PRIMARY KEY(`bookId`));
